  --ground: #0a0a0a; --surface: #131313; --panel: rgba(19, 19, 19, .9); --panel-hi: rgba(28, 28, 28, .94);
  --paper: #f5f3fa; --muted: #b3aec2; --faint: #91899f; --line: #2e2e2e; --steel: #91899f;
