{
  "name": "ohmyjev",
  "version": "0.12.0",
  "description": "Jev for Claude Code: Bash and Write gates, an injection screen, and a done-check, decided by TypeSafe's Jev.",
  "author": {
    "name": "lordknows13"
  },
  "license": "MIT",
  "keywords": [
    "mod",
    "function-hooks",
    "jev",
    "guardrails"
  ],
  "userConfig": {
    "enabled": {
      "type": "boolean",
      "title": "ohmyjev on",
      "description": "Off lets every call through. /omj off and /omj on change it for one session",
      "default": true
    },
    "apiKey": {
      "type": "string",
      "title": "TypeSafe API key",
      "description": "Empty uses $TYPESAFE_API_KEY, then $OPENROUTER_API_KEY",
      "default": "",
      "sensitive": true
    },
    "jevModel": {
      "type": "string",
      "title": "Jev model (TypeSafe)",
      "description": "Model id sent to the TypeSafe endpoint",
      "default": "jev-1.13.0"
    },
    "maskSecrets": {
      "type": "boolean",
      "title": "Mask secrets sent to Jev",
      "description": "Replace keys, tokens, credentials in URLs, emails and your home folder with markers in everything sent to Jev",
      "default": true
    },
    "timeoutMs": {
      "type": "number",
      "title": "Jev timeout (ms)",
      "description": "How long a gate, screen or the router waits for Jev before letting the call through",
      "default": 1500
    },
    "bashGate": {
      "type": "boolean",
      "title": "Bash gate",
      "description": "Deny irreversible or destructive commands",
      "default": true
    },
    "writeGate": {
      "type": "boolean",
      "title": "Write gate",
      "description": "Deny writes outside the repo/allowPaths and writes holding credentials",
      "default": true
    },
    "exfilGate": {
      "type": "boolean",
      "title": "Exfil gate",
      "description": "Deny WebFetch and MCP calls that send local data, files or credentials out",
      "default": true
    },
    "policies": {
      "type": "string",
      "title": "Policies",
      "description": "Your own rules every gate weighs, separated by ; (e.g. never touch prod; no deploys on Friday)",
      "default": ""
    },
    "allowPaths": {
      "type": "string",
      "title": "Allowed write paths outside the repo",
      "description": "Separated by ; (~ and $TMPDIR expand)",
      "default": "~/.claude;$TMPDIR;/tmp"
    },
    "bashIrreversible": {
      "type": "number",
      "title": "Bash: irreversible confidence to deny",
      "description": "Deny when Jev rates the command irreversible at least this confident (0-1)",
      "default": 0.6
    },
    "bashDestructive": {
      "type": "number",
      "title": "Bash: destructive-intent to deny",
      "description": "Deny when destructive intent is at least this probable (0-1)",
      "default": 0.7
    },
    "writeSecret": {
      "type": "number",
      "title": "Write: credential probability to deny",
      "description": "Deny when the content holds a credential at least this probable (0-1)",
      "default": 0.7
    },
    "writeSecretsKind": {
      "type": "number",
      "title": "Write: secrets-file confidence to deny",
      "description": "Deny when the file is a secrets file at least this confident (0-1)",
      "default": 0.8
    },
    "exfil": {
      "type": "number",
      "title": "Exfil probability to deny",
      "description": "Deny when Jev rates the call as sending local data out at least this probable (0-1)",
      "default": 0.7
    },
    "requested": {
      "type": "number",
      "title": "Let through what you asked for",
      "description": "A gate's Jev deny passes when Jev rates your latest message as asking for exactly that call at least this probable (0-1). Policy and path denies always stand",
      "default": 0.8
    },
    "injectionScreen": {
      "type": "boolean",
      "title": "Injection screen",
      "description": "Warn the model when Bash, WebFetch or MCP output carries instructions aimed at it",
      "default": true
    },
    "screenReads": {
      "type": "boolean",
      "title": "Screen Reads outside the repo",
      "description": "Run the injection screen on files read from outside the repo",
      "default": true
    },
    "doneCheck": {
      "type": "boolean",
      "title": "Done-check",
      "description": "Push back once when the agent claims done without verifying",
      "default": true
