    "subagentCheck": {
      "type": "boolean",
      "title": "Subagent checks",
      "description": "Send a vague subagent brief back once, and check a subagent's done against its own tool record",
      "default": true
    },
    "proseCheck": {
      "type": "boolean",
      "title": "Writing-rule check",
