      "default": true
    },
    "skillPick": {
      "type": "boolean",
      "title": "Skill picker",
      "description": "Leave the skill listing out of every prompt; Jev names the one skill a request needs (needs a Jev key)",
      "default": true
    },
    "readNarrow": {
      "type": "boolean",
      "title": "Narrow big reads",
      "description": "A Read of a 400+ line file comes back as the fifth Jev rates the request needs, with a note on how to read the rest. Saves tokens, adds about a second per big read",
      "default": false
    },
    "approveConfidence": {
      "type": "number",
      "title": "Auto-approve: Jev's confidence",
      "description": "How sure Jev must be that a command only reads or is reversible (0-1)",
      "default": 0.9
    },
    "approveRiskMax": {
      "type": "number",
      "title": "Auto-approve: highest risk",
