      "default": 0.2
    },
    "trimOver": {
      "type": "number",
      "title": "Trim outputs longer than",
      "description": "Characters of shell output before trimming is considered",
      "default": 12000
    },
    "trimKeep": {
      "type": "number",
      "title": "Trim: keep a part at",
      "description": "How likely Jev must rate a part as needed for it to stay (0-1)",
      "default": 0.3
    },
    "skillGate": {
      "type": "number",
      "title": "Skill picker: needs a skill at",
      "description": "How strongly Jev must rate a request as needing a skill before one is named (0-1)",
      "default": 0.3
    },
    "skillMin": {
      "type": "number",
      "title": "Skill picker: pick confidence",
      "description": "How sure Jev must be of which skill fits (0-1)",
      "default": 0.4
    },
    "fastCompact": {
      "type": "boolean",
      "title": "Fast compaction",
      "description": "Compact in about a second: Jev keeps the messages that still matter, verbatim, instead of a model writing a summary",
      "default": true
    },
    "autoCompact": {
      "type": "boolean",
      "title": "Auto-compact",
      "description": "Compact when Jev sees the task change at a natural boundary, keeping the new request in detail",
      "default": true
    },
    "compactSwitched": {
      "type": "number",
      "title": "Auto-compact: task-switch probability",
      "description": "Compact when the request switched tasks at least this probable (0-1)",
      "default": 0.8
    },
    "compactBoundary": {
      "type": "number",
      "title": "Auto-compact: boundary probability",
      "description": "…and the last turn finished a unit of work at least this probable (0-1)",
      "default": 0.6
    },
    "compactMinPercent": {
      "type": "number",
      "title": "Auto-compact: minimum context %",
      "description": "Only compact once the context is at least this full (0-100)",
      "default": 40
    },
    "routeEffort": {
      "type": "boolean",
      "title": "Router: effort",
      "description": "Raise or lower reasoning effort per turn from Jev's read of the request",
      "default": true
    },
    "routeSubagents": {
